-- Generated by schema/build.mjs from facet "memoir" v0. Do not edit.
-- One table per list (id TEXT PRIMARY KEY, columns, updated_at) plus an append-only
-- memoir_ops table: undo is a superseding op, nothing is rewritten in place.

CREATE TABLE IF NOT EXISTS memoir_chapters (
  id TEXT PRIMARY KEY,
  "title" TEXT NOT NULL CHECK ("title" IS NULL OR (length("title") >= 1 AND length("title") <= 120)),
  "body" TEXT NOT NULL CHECK ("body" IS NULL OR (length("body") <= 20000)),
  "updated_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS memoir_ops (
  op_id TEXT PRIMARY KEY,
  receipt_id TEXT NOT NULL,
  op TEXT NOT NULL CHECK (op IN ('add', 'set', 'remove', 'undo')),
  list TEXT CHECK (list IS NULL OR list IN ('chapters')),
  item_id TEXT,
  value_json TEXT CHECK (value_json IS NULL OR json_valid(value_json)),
  at TEXT NOT NULL,
  supersedes TEXT REFERENCES memoir_ops (op_id)
);
CREATE INDEX IF NOT EXISTS memoir_ops_receipt ON memoir_ops (receipt_id);
